function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function norm(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function stored(key){try{return localStorage.getItem(key);}catch{return null;}}
function remember(key,value){try{localStorage.setItem(key,value);}catch{}}
function browserLanguage(){for(const value of navigator.languages||[navigator.language]){const code=String(value||'').toLowerCase().split('-')[0];if(code==='en'||code==='pt')return code;}return'en';}
let interfaceLanguage=stored('interface-language')||browserLanguage();if(!copy[interfaceLanguage])interfaceLanguage='en';
let recipeLanguage=stored('recipe-language');if(recipeLanguage==='native'||!['en','pt'].includes(recipeLanguage)){recipeLanguage=interfaceLanguage;remember('recipe-language',recipeLanguage);}
let activeContentLanguage=null;const recipeHeadingKeys=new Set(['yield','servings','prep','cook','total']);
function tr(key){const language=recipeHeadingKeys.has(key)&&activeContentLanguage?activeContentLanguage:interfaceLanguage;return copy[language][key];}
function displayRecipe(r){activeContentLanguage=recipeLanguage===r.language_code||r.translations?.[recipeLanguage]?recipeLanguage:r.language_code;if(recipeLanguage===r.language_code)return r;const translated=r.translations?.[recipeLanguage];return translated?{...r,...translated}:r;}
function actualRecipeLanguage(r){return recipeLanguage===r.language_code||r.translations?.[recipeLanguage]?recipeLanguage:r.language_code;}
function setInterfaceLanguage(code){interfaceLanguage=copy[code]?code:'en';remember('interface-language',interfaceLanguage);applyInterface();editionChrome();categoryOptions();search();route();}
function setRecipeLanguage(code){recipeLanguage=['en','pt'].includes(code)?code:'en';remember('recipe-language',recipeLanguage);document.querySelectorAll('input[name=recipe-language]').forEach(n=>n.checked=n.value===recipeLanguage);search();route();}
function applyInterface(){document.documentElement.lang=interfaceLanguage;$('interface-language').value=interfaceLanguage;const ids={'interface-language-label':'siteLanguage','about-link':'aboutLink','hero-eyebrow':'heroEyebrow','hero-lead':'heroLead','collection-label':'collection','kind-label':'show','search-heading':'searchHeading','recipe-language-legend':'recipeLanguage','about-eyebrow':'aboutEyebrow','about-title':'aboutTitle','about-one':'aboutOne','about-two':'aboutTwo','back-link':'back','more':'more'};for(const[id,key]of Object.entries(ids))$(id).textContent=tr(key);$('hero-title').innerHTML=tr('heroTitle');$('collection-note').innerHTML=tr('collectionNote');$('search').placeholder=tr('searchPlaceholder');$('category').setAttribute('aria-label',tr('category'));$('collection').options[0].textContent=tr('allCollections');$('category').options[0].textContent=tr('everyCategory');tr('kinds').forEach((label,i)=>$('kind').options[i].textContent=label);$('search-panel').setAttribute('aria-label',tr('searchHeading'));}
function card(native){const recipe=displayRecipe(native),lang=actualRecipeLanguage(native),a=el('a',undefined,'recipe-card');a.href='#recipe/'+recipe.id;a.lang=lang;a.append(el('p',[recipe.collection?.name,recipe.content_kind==='recipe'?recipe.categories?.[0]:recipe.content_kind].filter(Boolean).join(' · '),'category'),el('h3',recipe.title));if(recipe.description)a.append(el('p',recipe.description,'description'));return a;}
function more(){for(const r of filtered.slice(shown,shown+24))$('cards').append(card(r));shown+=24;$('more').hidden=shown>=filtered.length;}
function categoryOptions(){if(!edition)return;const selected=$('category').value,collection=$('collection').value,counts=new Map();for(const r of all.filter(r=>!collection||r.collection?.slug===collection))for(const c of r.categories||[])counts.set(c,(counts.get(c)||0)+1);$('category').replaceChildren();const empty=el('option',tr('everyCategory'));empty.value='';$('category').append(empty);for(const[name,count]of[...counts].sort((a,b)=>a[0].localeCompare(b[0]))){const option=el('option',name+' ('+count+')');option.value=name;$('category').append(option);}$('category').value=counts.has(selected)?selected:'';}
function search(){if(!edition)return;const terms=norm($('search').value).trim().split(/\s+/).filter(Boolean),category=$('category').value;filtered=all.filter(r=>(!$('collection').value||r.collection?.slug===$('collection').value)&&(!$('kind').value||r.content_kind===$('kind').value)&&(!category||r.categories?.includes(category))&&terms.every(t=>r.searchText.includes(t)));filtered.sort((a,b)=>displayRecipe(a).title.localeCompare(displayRecipe(b).title,recipeLanguage));$('result-count').textContent=`${filtered.length} ${filtered.length===1?tr('entry'):tr('entries')}`;$('results-title').textContent=terms.length||category?tr('fromSearch'):tr('explore');$('cards').replaceChildren();shown=0;more();if(!filtered.length)$('cards').append(el('p',tr('none')));}
function recipeLanguageControl(){const box=el('fieldset',undefined,'recipe-language detail-language'),legend=el('legend',tr('recipeLanguage'));box.append(legend);for(const[code,label]of[['en','🇺🇸 English'],['pt','🇧🇷 Português']]){const wrap=el('label'),input=el('input');input.type='radio';input.name='detail-recipe-language';input.value=code;input.checked=recipeLanguage===code;input.onchange=()=>setRecipeLanguage(code);wrap.append(input,el('span',label));box.append(wrap);}return box;}
function showRecipe(native){const recipe=displayRecipe(native),lang=actualRecipeLanguage(native);$('browse').hidden=true;$('detail').hidden=false;const root=$('recipe-content');root.replaceChildren(recipeLanguageControl());if(lang!==recipeLanguage)root.append(el('p',tr('unavailable'),'availability'));const heading=el('section',undefined,'detail-heading');heading.lang=lang;const print=el('button',tr('print'),'print-button');print.onclick=()=>window.print();heading.append(print,el('p',[recipe.collection?.name,...(recipe.categories||[]),recipe.content_kind!=='recipe'?recipe.content_kind:''].filter(Boolean).join(' · '),'category'),el('h1',recipe.title));if(recipe.description)heading.append(el('p',recipe.description,'detail-description'));const meta=el('div',undefined,'recipe-meta');for(const[label,value]of[[tr('yield'),recipe.yield],[tr('servings'),recipe.servings],[tr('prep'),recipe.prep_time],[tr('cook'),recipe.cook_time],[tr('total'),recipe.total_time]])if(value){const item=el('div');item.append(el('strong',label),document.createTextNode(value));meta.append(item);}if(meta.childElementCount)heading.append(meta);root.append(heading);if(recipe.photos.length){const photos=el('div',undefined,'photos');for(const p of recipe.photos){const figure=el('figure'),img=el('img');img.src='/data/'+p.url;img.alt=p.caption||recipe.title;img.loading='lazy';figure.append(img);if(p.caption)figure.append(el('figcaption',p.caption));photos.append(figure);}root.append(photos);}const labels=copy[lang]||copy.en,layout=el('div',undefined,'recipe-layout'),ingredients=el('section',undefined,'ingredients'),method=el('section',undefined,'method');layout.lang=lang;ingredients.append(el('h2',labels.ingredients));const list=el('ul');for(const line of recipe.ingredients)list.append(el('li',line));if(!recipe.ingredients.length)ingredients.append(el('p',labels.noIngredients));ingredients.append(list);method.append(el('h2',labels.method));if(recipe.steps.length){const steps=el('ol');for(const step of recipe.steps)steps.append(el('li',step.replace(/\s+---\s*$/,'')));method.append(steps);}else method.append(el('pre',recipe.instructions||labels.noProcedure));if(recipe.notes){const notes=el('div',undefined,'notes');notes.append(el('h3',labels.notes),el('p',recipe.notes));method.append(notes);}layout.append(ingredients,method);root.append(layout);if(recipe.originals.length){const section=el('section',undefined,'originals');section.append(el('h2',tr('sourceTitle')),el('p',tr('sourceIntro')));for(const o of recipe.originals){const detail=el('details'),summary=el('summary',o.source_kind==='transcription'?tr('transcription'):o.document_name+(o.locator?' · '+o.locator.split(';')[0]:'')),content=el('div',undefined,'source-content');content.append(el('p',(o.source_kind==='transcription'?tr('derived'):tr('captured'))+(o.locator?' · '+o.locator:''),'source-label'),el('pre',o.text));detail.append(summary,content);section.append(detail);}root.append(section);}document.title=recipe.title+' · Tia Luiza’s Recipe Box';window.scrollTo(0,0);}
function route(){const match=location.hash.match(/^#recipe\/(\d+)$/);if(match){const recipe=all.find(r=>r.id===Number(match[1]));if(recipe){showRecipe(recipe);return;}}$('browse').hidden=false;$('detail').hidden=true;document.title='Tia Luiza’s Recipe Box';if(location.hash!=='#about')window.scrollTo(0,0);}
function editionChrome(){if(!edition)return;const collections=new Set(all.filter(r=>r.collection).map(r=>r.collection.slug));const date=new Date(edition.created_at).toLocaleDateString(interfaceLanguage==='pt'?'pt-BR':'en-US',{year:'numeric',month:'short',day:'numeric'});$('edition-label').textContent=all.length+' '+tr('entries')+' · '+collections.size+' '+tr('collections');$('footer-edition').textContent=(edition.preview?tr('preview'):tr('published'))+' · '+date;}
$('interface-language').onchange=()=>setInterfaceLanguage($('interface-language').value);document.querySelectorAll('input[name=recipe-language]').forEach(n=>{n.checked=n.value===recipeLanguage;n.onchange=()=>setRecipeLanguage(n.value);});$('collection').onchange=()=>{categoryOptions();search();};$('kind').onchange=search;$('search').oninput=search;$('category').onchange=search;$('more').onclick=more;window.addEventListener('hashchange',route);applyInterface();
// Revalidate the small manifest; reuse recipe bytes until their content hash changes.
async function loadRecipeEdition(){
 const message='The recipe edition could not be loaded. Please try again.';
 const manifestResponse=await fetch('data/edition.json',{cache:'no-cache'});
 if(!manifestResponse.ok)throw Error(message);
 const manifest=await manifestResponse.json();
 const hash=manifest.files?.['recipes.json'];
 if(!/^[a-f0-9]{64}$/.test(hash))throw Error(message);
 const response=await fetch('data/recipes.json?v='+hash,{cache:'force-cache'});
 if(!response.ok)throw Error(message);
 return response.json();
}
(async()=>{try{edition=await loadRecipeEdition();all=edition.recipes.map(r=>({...r,searchText:norm([r.title,r.description,...(r.ingredient_search_terms||[]),...r.ingredients,...r.steps,r.notes,...Object.values(r.translations||{}).flatMap(t=>[t.title,t.description,...t.ingredients,...t.steps,t.notes])].join(' '))})).sort((a,b)=>a.title.localeCompare(b.title,'pt'));const collections=[...new Map(all.filter(r=>r.collection).map(r=>[r.collection.slug,r.collection])).values()];for(const c of collections){const o=el('option',c.name+' ('+all.filter(r=>r.collection?.slug===c.slug).length+')');o.value=c.slug;$('collection').append(o);}const date=new Date(edition.created_at).toLocaleDateString(interfaceLanguage==='pt'?'pt-BR':'en-US',{year:'numeric',month:'short',day:'numeric'});$('edition-label').textContent=all.length+' '+tr('entries')+' · '+collections.length+' '+tr('collections');$('footer-edition').textContent=(edition.preview?tr('preview'):tr('published'))+' · '+date;categoryOptions();search();route();}catch(e){$('error').hidden=false;$('error').textContent=e.message;$('result-count').textContent=tr('unavailableCollection');}})();
